def gen(rng):
    def build(n, mode='random', vals=None):
        # returns left, right arrays (index based), node 0 is root
        L = [-1] * n
        R = [-1] * n
        if mode == 'random':
            slots = [(0, 0), (0, 1)]
            for k in range(1, n):
                idx = rng.randrange(len(slots))
                slots[idx], slots[-1] = slots[-1], slots[idx]
                p, side = slots.pop()
                if side == 0:
                    L[p] = k
                else:
                    R[p] = k
                slots.append((k, 0))
                slots.append((k, 1))
        elif mode == 'left':
            for k in range(1, n):
                L[k - 1] = k
        elif mode == 'right':
            for k in range(1, n):
                R[k - 1] = k
        elif mode == 'zigzag':
            for k in range(1, n):
                if k % 2:
                    L[k - 1] = k
                else:
                    R[k - 1] = k
        elif mode == 'perfect':
            for k in range(1, n):
                p = (k - 1) // 2
                if k % 2:
                    L[p] = k
                else:
                    R[p] = k
        return L, R

    def serialize(L, R, vals):
        out = [str(vals[0])]
        q = [0]
        h = 0
        while h < len(q):
            u = q[h]
            h += 1
            for c in (L[u], R[u]):
                if c == -1:
                    out.append('null')
                else:
                    out.append(str(vals[c]))
                    q.append(c)
        while out[-1] == 'null':
            out.pop()
        return ' '.join(out)

    def make(n, mode='random', lo=-50, hi=50):
        L, R = build(n, mode)
        vals = [rng.randint(lo, hi) for _ in range(n)]
        return serialize(L, R, vals)

    tests = ['1', '1 2', '1 null 2', '1 2 3 4 5 7 6', '5 null 8 null 9', '10 -2 7 null 4 3', '0 0 0 0 0 0 0']
    for n in range(2, 14):
        for mode in ('random', 'random', 'left', 'right', 'zigzag', 'perfect'):
            if rng.random() < 0.5:
                tests.append(make(n, mode))
    for _ in range(25):
        tests.append(make(rng.randint(1, 40), 'random'))
    big = 10**9
    tests.append(make(100000, 'random', -big, big))
    tests.append(make(2**16 - 1, 'perfect', -big, big))
    tests.append(make(5000, 'left', -big, big))
    tests.append(make(5000, 'right', -big, big))
    tests.append(make(4999, 'zigzag', -big, big))
    tests.append(make(99999, 'perfect', -big, big))
    return tests
